window.AUTH=window.AUTH||{};window.AUTH["18-1432"]={"d":"18-1432","id":"2019/18-1432","n":"Nasrallah v. Barr","briefs":[{"k":"petitioner","label":"Brief of petitioner Nidal Khalid Nasrallah","date":"2019-12-09","url":"https://www.supremecourt.gov/DocketPDF/18/18-1432/124898/20191209135824866_18-1432.ts.brief.pdf","side":"pet","n":44},{"k":"respondent","label":"Brief of respondent William P. Barr, Attorney General","date":"2020-01-15","url":"https://www.supremecourt.gov/DocketPDF/18/18-1432/128810/20200115194839439_18-1432bsUnitedStates.pdf","side":"res","n":109},{"k":"reply","label":"Reply of petitioner Nidal Khalid Nasrallah","date":"2020-02-14","url":"https://www.supremecourt.gov/DocketPDF/18/18-1432/133024/20200214112724483_18-1432.reply.brief.pdf","side":"pet","n":42}],"opinion":"https://www.supremecourt.gov/opinions/preliminaryprint/590US2PP_web.pdf#page=161","tr":true,"items":[{"t":"case","label":"Albathani v. INS","cite":"318 F.3d 365","y":2003,"court":"1st Cir.","url":"https://www.courtlistener.com/c/F.3d/318/365/","by":{"0":"38"}},{"t":"case","label":"Ardestani v. INS","cite":"502 U.S. 129","y":1991,"id":"1991/90-1141","sc":1,"by":{"0":"38"}},{"t":"case","label":"Arej v. Sessions","cite":"852 F.3d 665","y":2017,"court":"7th Cir.","url":"https://www.courtlistener.com/c/F.3d/852/665/","by":{"0":"39"}},{"t":"case","label":"Bowen v. Michigan Acad. of Family Physicians","cite":"476 U.S. 667","y":1986,"id":"1985/85-225","sc":1,"by":{"0":"36"}},{"t":"case","label":"Burgess v. United States","cite":"553 U.S. 124","y":2008,"id":"2007/06-11429","sc":1,"by":{"0":"26, 33","2":"6, 10, 12"},"q":[{"src":"brief","b":0,"text":"[a]s a rule, a [statutory] definition which declares what a term ‘means’ excludes any meaning that is not stated.","cite":"553 U.S. 124, 131"}]},{"t":"case","label":"Calcano-Martinez v. INS","cite":"533 U.S. 348","y":2001,"id":"2000/00-1011","sc":1,"by":{"0":"3, 26","1":"2"}},{"t":"case","label":"Corley v. United States","cite":"556 U.S. 303","y":2009,"id":"2008/07-10441","sc":1,"by":{"0":"29, 30"},"q":[{"src":"brief","b":0,"text":"a statute should be construed so that effect is given to all its provisions, so that no part will be inoperative or superfluous, void or insignificant.","cite":"556 U.S. 303, 314"}]},{"t":"case","label":"Cuozzo Speed Techs., LLC v. Lee","cite":"136 S. Ct. 2131","y":2016,"id":"2015/15-446","sc":1,"by":{"0":"37","1":"37"},"q":[{"src":"brief","b":0,"text":"[i]f a provision can reasonably be read to permit judicial review, it should be.","cite":"136 S. Ct. 2131, 2150"},{"src":"brief","b":0,"text":"serves to buttress * * * Congress’s objectives.","cite":"136 S. Ct. at 2151"},{"src":"brief","b":1,"text":"may be overcome by clear and convincing indications, drawn from specific language, specific legislative history, and inferences of intent drawn from the statutory scheme as a whole, that Congress intended to bar review.","cite":"136 S. Ct. 2131, 2140"}]},{"t":"case","label":"Cyan, Inc. v. Beaver Cty. Emps. Ret. Fund","cite":"138 S. Ct. 1061","y":2018,"id":"2017/15-1439","sc":1,"by":{"0":"24, 36"}},{"t":"case","label":"Digital Realty Tr., Inc. v. Somers","cite":"138 S. Ct. 767","y":2018,"id":"2017/16-1276","sc":1,"by":{"0":"33","2":"10, 12"}},{"t":"case","label":"Food Mktg. Inst. v. Argus Leader Media","cite":"139 S. Ct. 2356","y":2019,"id":"2018/18-481","sc":1,"by":{"0":"23","1":"16"},"q":[{"src":"brief","b":0,"text":"In statutory interpretation disputes, a court’s proper starting point lies in a careful examination of the ordinary meaning and structure of the law itself.","cite":"139 S. Ct. 2356, 2364"}]},{"t":"case","label":"Foti v. INS","cite":"375 U.S. 217","y":1963,"id":"1963/28","sc":1,"by":{"0":"32, 33, 34","1":"passim","2":"passim"},"q":[{"src":"brief","b":1,"text":"review of all final orders of deportation.","cite":"375 U.S. 217"},{"src":"brief","b":1,"text":"no deportation order [being] rendered at all.","cite":"375 U.S. at 223"},{"src":"argument","who":"Justice Kavanaugh","text":"Can you address the government's reliance on Foti and why that decision doesn't carry forward?"},{"src":"argument","who":"Mr. Hughes","text":"A few things about Foti, Your Honor. First, we think the holding in Foti is completely consistent with our position and with the --"},{"src":"argument","who":"Justice Kavanaugh","text":"The language in Foti."}]},{"t":"case","label":"Guzman Chavez v. Hott","cite":"940 F.3d 867","y":2019,"court":"4th Cir.","url":"https://www.courtlistener.com/c/F.3d/940/867/","by":{"0":"8"},"q":[{"src":"argument","who":"Mr. Hughes","text":"In the Guzman Chavez cert petition at page 10 -- they filed this after their brief -- they say, \"withholding does not address whether an alien is ordered removed.\" It's the government's position that whether an alien is ordered removed, that binary determination, is made by the final order of removal, not the CAT claim."}]},{"t":"case","label":"Heller v. New York","cite":"413 U.S. 483","y":1973,"id":"1972/71-1043","sc":1,"by":{"0":"45"}},{"t":"case","label":"INS v. Chadha","cite":"462 U.S. 919","y":1983,"id":"1981/80-1832","sc":1,"by":{"0":"32, 33","1":"20, 21","2":"9, 13, 14"},"q":[{"src":"brief","b":1,"text":"the term ‘final orders’ * * * ‘includes all matters on which the validity of the final order is contingent,’","cite":"462 U.S. at 938"},{"src":"argument","who":"Mr. Hughes","text":"I think the merger principle this Court identified in Chadha is the correct one, which is to say anything on which the final order of removal is contingent would appropriately merge into that and be governed by 2(C)."}]},{"t":"case","label":"INS v. St. Cyr","cite":"533 U.S. 289","y":2001,"id":"2000/00-767","sc":1,"by":{"0":"11, 28","1":"6, 25, 30, 31","2":"8, 11, 17"},"q":[{"src":"opinion","who":"Opinion of the Court (Justice Kavanaugh)","text":"consolidated in a petition for review and considered by the courts of appeals.","cite":"533 U. S. 289, 313"}]},{"t":"case","label":"Jahjaga v. Attorney Gen.","cite":"512 F.3d 80","y":2008,"court":"3d Cir.","url":"https://www.courtlistener.com/c/F.3d/512/80/","by":{"0":"37"},"q":[{"src":"brief","b":0,"text":"the content and reasoning of the BIA opinion can mean life or death to a deportee.","cite":"512 F.3d 80, 85"}]},{"t":"case","label":"Kawashima v. Holder","cite":"132 S. Ct. 1166","y":2012,"id":"2011/10-577","sc":1,"by":{"0":"37"},"q":[{"src":"brief","b":0,"text":"ambiguities in deportation statutes in the alien’s favor.","cite":"132 S. Ct. 1166, 1176"}]},{"t":"case","label":"Kucana v. Holder","cite":"558 U.S. 233","y":2010,"id":"2009/08-911","sc":1,"by":{"0":"37"},"q":[{"src":"brief","b":0,"text":"takes ‘clear and convincing evidence’ to dislodge the presumption","cite":"558 U.S. 233, 252"},{"src":"brief","b":0,"text":"against reading legislation, absent clear statement, to place in executive hands authority to remove cases from the Judiciary’s domain.","cite":"558 U.S. at 237"}]},{"t":"case","label":"Mach Mining, LLC v. EEOC","cite":"135 S. Ct. 1645","y":2015,"url":"https://www.courtlistener.com/c/S.%20Ct./135/1645/","sc":1,"by":{"0":"36, 37"}},{"t":"case","label":"Michigan v. Bay Mills Indian Cmty.","cite":"572 U.S. 782","y":2014,"id":"2013/12-515","sc":1,"by":{"0":"24"}},{"t":"case","label":"Moncrieffe v. Holder","cite":"569 U.S. 184","y":2013,"id":"2012/11-702","sc":1,"by":{"0":"8, 9"},"q":[{"src":"brief","b":0,"text":"has no discretion to deny relief to a noncitizen who establishes his eligibility","cite":"569 U.S. 184, 187 n.1"}]},{"t":"case","label":"Nken v. Holder","cite":"556 U.S. 418","y":2009,"id":"2008/08-681","sc":1,"by":{"0":"26"}},{"t":"case","label":"Reno v. Catholic Social Servs., Inc.","cite":"509 U.S. 43","y":1993,"id":"1992/91-1826","sc":1,"by":{"0":"36, 37"}},{"t":"case","label":"Rodriguez-Roman v. INS","cite":"98 F.3d 416","y":1996,"court":"9th Cir.","url":"https://www.courtlistener.com/c/F.3d/98/416/","by":{"0":"38"}},{"t":"case","label":"Russello v. United States","cite":"464 U.S. 16","y":1983,"id":"1983/82-472","sc":1,"by":{"0":"30"}},{"t":"case","label":"Smith v. Berryhill","cite":"139 S. Ct. 1765","y":2019,"id":"2018/17-1606","sc":1,"by":{"0":"22, 36, 37"},"q":[{"src":"brief","b":0,"text":"strong presumption that Congress intends judicial review of administrative action.","cite":"139 S. Ct. 1765, 1776"},{"src":"brief","b":0,"text":"the burden for rebutting it is ‘heavy.’","cite":"139 S. Ct. at 1776"}]},{"t":"case","label":"Sturgeon v. Frost","cite":"139 S. Ct. 1066","y":2019,"id":"2018/17-949","sc":1,"by":{"0":"26"}},{"t":"case","label":"United States v. Nourse","cite":"34 U.S. 8","y":1835,"id":"scdb/1835-008","sc":1,"by":{"0":"36"}},{"t":"case","label":"Virginia Uranium, Inc. v. Warren","cite":"139 S. Ct. 1894","y":2019,"id":"2018/16-1275","sc":1,"by":{"0":"24, 36"}},{"t":"case","label":"Zhang v. Gonzales","cite":"452 F.3d 167","y":2006,"court":"2d Cir.","url":"https://www.courtlistener.com/c/F.3d/452/167/","by":{"0":"39"}},{"t":"reg","label":"8 C.F.R. § 236.4","url":"https://www.ecfr.gov/current/title-8/section-236.4","subs":["(e)"],"by":{"0":"43"}},{"t":"reg","label":"8 C.F.R. § 1208.24","url":"https://www.ecfr.gov/current/title-8/section-1208.24","subs":["(b)(1)"],"by":{"0":"8"}},{"t":"usc","label":"8 U.S.C. § 1101","url":"https://www.law.cornell.edu/uscode/text/8/1101","subs":["(a)(3)","(a)(43)(G)","(a)(47)(A)","(a)(47)(B)","(a)(47)"],"stext":{"head":"§1101. Definitions","paras":[[0,"(a) As used in this chapter—"],[0,"(1) The term \"administrator\" means the official designated by the Secretary of State pursuant to section 1104(b) of this title."],[0,"(2) The term \"advocates\" includes, but is not limited to, advises, recommends, furthers by overt act, and admits belief in."],[0,"(3) The term \"alien\" means any person not a citizen or national of the United States."],[0,"(4) The term \"application for admission\" has reference to the application for admission into the United States and not to the application for the issuance of an immigrant or nonimmigrant visa."],[0,"(5) The term \"Attorney General\" means the Attorney General of the United States."],[0,"(6) The term \"border crossing identification card\" means a document of identity bearing that designation issued to an alien who is lawfully admitted for permanent residence, or to an alien who is a resident in foreign contiguous territory, by a consular officer or an immigration officer for the purpose of crossing over the borders between the United States and foreign contiguous territory in accordance with such conditions for its issuance and use as may be prescribed by regulations. Such regulations shall provide that (A) each such document include a biometric identifier (such as the fingerprint or handprint of the alien) that is machine readable and (B) an alien presenting a border crossing identification card is not permitted to cross over the border into the United States unless the biometric identifier contained on the card matches the appropriate biometric characteristic of the alien."],[0,"(7) The term \"clerk of court\" means a clerk of a naturalization court."],[0,"(8) The terms \"Commissioner\" and \"Deputy Commissioner\" mean the Commissioner of Immigration and Naturalization and a Deputy Commissioner of Immigration and Naturalization, respectively."],[0,"(9) The term \"consular officer\" means any consular, diplomatic, or other officer or employee of the United States designated under regulations prescribed under authority contained in this chapter, for the purpose of issuing immigrant or nonimmigrant visas or, when used in subchapter III, for the purpose of adjudicating nationality."],[0,"(10) The term \"crewman\" means a person serving in any capacity on board a vessel or aircraft."],[0,"(11) The term \"diplomatic visa\" means a nonimmigrant visa bearing that title and issued to a nonimmigrant in accordance with such regulations as the Secretary of State may prescribe."],[0,"(12) The term \"doctrine\" includes, but is not limited to, policies, practices, purposes, aims, or procedures."],[0,"(13)(A) The terms \"admission\" and \"admitted\" mean, with respect to an alien, the lawful entry of the alien into the United States after inspection and authorization by an immigration officer."],[0,"(B) An alien who is paroled under section 1182(d)(5) of this title or permitted to land temporarily as an alien crewman shall not be considered to have been admitted."],[0,"(C) An alien lawfully admitted for permanent residence in the United States shall not be regarded as seeking an admission into the United States for purposes of the immigration laws unless the alien—"],[1,"(i) has abandoned or relinquished that status,"],[1,"(ii) has been absent from the United States for a continuous period in excess of 180 days,"],[1,"(iii) has engaged in illegal activity after having departed the United States,"],[1,"(iv) has departed from the United States while under legal process seeking removal of the alien from the United States, including removal proceedings under this chapter and extradition proceedings,"],[1,"(v) has committed an offense identified in section 1182(a)(2) of this title, unless since such offense the alien has been granted relief under section 1182(h) or 1229b(a) of this title, or"],[1,"(vi) is attempting to enter at a time or place other than as designated by immigration officers or has not been admitted to the United States after inspection and authorization by an immigration officer."],[0,"(14) The term \"foreign state\" includes outlying possessions of a foreign state, but self-governing dominions or territories under mandate or trusteeship shall be regarded as separate foreign states."],[0,"(15) The term \"immigrant\" means every alien except an alien who is within one of the following classes of nonimmigrant aliens—"],[1,"(A)(i) an ambassador, public minister, or career diplomatic or consular officer who has been accredited by a foreign government, recognized de jure by the United States and who is accepted by the President or by the Secretary of State, and the members of the alien's immediate family;"],[1,"(ii) upon a basis of reciprocity, other officials and employees who have been accredited by a foreign government recognized de jure by the United States, who are accepted by the Secretary of State, and the members of their immediate families; and"],[1,"(iii) upon a basis of reciprocity, attendants, servants, personal employees, and members of their immediate families, of the officials and employees who have a nonimmigrant status under (i) and (ii) above;"],[1,"(B) an alien (other than one coming for the purpose of study or of performing skilled or unskilled labor or as a representative of foreign press, radio, film, or other foreign information media coming to engage in such vocation) having a residence in a foreign country which he has no intention of abandoning and who is visiting the United States temporarily for business or temporarily for pleasure;"],[1,"(C)(i) an alien in immediate and continuous transit through the United States, for a period not to exceed 29 days;"],[1,"(ii) an alien who qualifies as a person entitled to pass in transit to and from the United Nations Headquarters District (as defined in section 4309a(e) of title 22) and foreign countries, under the provisions of paragraphs (3), (4), and (5) of section 11 of the Agreement regarding the Headquarters of the United Nations, done at Lake Success June 26, 1947 (61 Stat. 758); or"],[1,"(iii) an alien passing in transit through the United States to board a vessel on which the alien will perform, or to disembark from a vessel on which the alien performed, ship-to-ship liquid cargo transfer operations to or from another vessel engaged in foreign trade, for a period not to exceed 180 days;"],[1,"(D)(i) an alien crewman serving in good faith as such in a capacity required for normal operation and service on board a vessel, as defined in section 1288(a) of this title (other than a fishing vessel having its home port or an operating base in the United States), or aircraft, who intends to land temporarily and solely in pursuit of his calling as a crewman and to depart from the United States with the vessel or aircraft on which he arrived or some other vessel or aircraft;"],[1,"(ii) an alien crewman serving in good faith as such in any capacity required for normal operations and service aboard a fishing vessel having its home port or an operating base in the United States who intends to land temporarily in Guam or the Commonwealth of the Northern Mariana Islands and solely in pursuit of his calling as a crewman and to depart from Guam or the Commonwealth of the Northern Mariana Islands with the vessel on which he arrived; or"],[1,"(iii) an alien crewman performing ship-to-ship liquid cargo transfer operations to or from another vessel engaged in foreign trade, who intends to land temporarily solely in pursuit of the alien's responsibilities as a crewman and to depart from the United States on the vessel on which the alien arrived or on another vessel or aircraft, for a period not to exceed 180 days;"],[1,"(E) an alien entitled to enter the United States under and in pursuance of the provisions of a treaty of commerce and navigation between the United States and the foreign state of which the alien is a national (or, in the case of an alien who acquired the relevant nationality through a financial investment and who has not previously been granted status under this subparagraph, the foreign state of which the alien is a national and in which the alien has been domiciled for a continuous period of not less than 3 years at any point before applying for a nonimmigrant visa under this subparagraph), and the spouse and children of any such alien if accompanying or following to join such alien; (i) solely to carry on substantial trade, including trade in services or trade in technology, principally between the United States and the foreign state of which the alien is a national; (ii) solely to develop and direct the operations of an enterprise in which the alien has invested, or of an enterprise in which the alien is actively in the process of investing, a substantial amount of capital; or (iii) solely to perform services in a specialty occupation in the United States if the alien is a national of the Commonwealth of Australia and with respect to whom the Secretary of Labor determines and certifies to the Secretary of Homeland Security and the Secretary of State that the intending employer has filed with the Secretary of Labor an attestation under section 1182(t)(1) of this title;"],[1,"(F)(i) an alien having a residence in a foreign country which he has no intention of abandoning, who is a bona fide student qualified to pursue a full course of study and who seeks to enter the United States temporarily and solely for the purpose of pursuing such a course of study consistent with section 1184(l) 1 of this title at an established college, university, seminary, conservatory, academic high school, elementary school, or other academic institution or in an accredited language training program in the United States, particularly designated by him and approved by the Attorney General after consultation with the Secretary of Education, which institution or place of study shall have agreed to report to the Attorney General the termination of attendance of each nonimmigrant student, and if any such institution of learning or place of study fails to make reports promptly the approval shall be withdrawn, (ii) the alien spouse and minor children of any alien described in clause (i) if accompanying or following to join such an alien, and (iii) an alien who is a national of Canada or Mexico, who maintains actual residence and place of abode in the country of nationality, who is described in clause (i) except that the alien's qualifications for and actual course of study may be full or part-time, and who commutes to the United States institution or place of study from Canada or Mexico;"]],"more":true,"ed":"2024","src":"https://www.govinfo.gov/link/uscode/8/1101?type=usc&year=mostrecent&link-type=html"},"by":{"0":"4","1":"2, 8, 3, 24, 24","2":"2, 6, 10, 11"},"q":[{"src":"brief","b":0,"text":"conclud[es] that the alien is deportable or order[s] deportation.","cite":"8 U.S.C. § 1101(a)(47)(A)"},{"src":"brief","b":0,"text":"order * * * concluding that the alien is deportable or ordering deportation.","cite":"8 U.S.C. § 1101(a)(47)(A)"},{"src":"brief","b":1,"text":"theft offense (including receipt of stolen property) * * * for which the term of imprisonment [is] at least one year.","cite":"8 U.S.C. 1101(a)(43)(G)"},{"src":"brief","b":1,"text":"[t]he term ‘order of deportation’ means the order of the special inquiry officer, or other such administrative officer to whom the Attorney General has delegated the responsibility for determining whether an alien is deportable, concluding that the alien is deportable or ordering deportation.","cite":"8 U.S.C. 1101(a)(47)(A)"},{"src":"opinion","who":"Opinion of the Court (Justice Kavanaugh)","text":"concluding that the alien is deportable or ordering deportation.","cite":"8 U. S. C. § 1101(a)(47)(A)"}]},{"t":"usc","label":"8 U.S.C. § 1229a","url":"https://www.law.cornell.edu/uscode/text/8/1229a","subs":["(e)(2)(B)","(c)(1)(A)"],"stext":{"head":"§1229a. Removal proceedings","paras":[[0,"(a) Proceeding"],[0,"(1) In general"],[1,"An immigration judge shall conduct proceedings for deciding the inadmissibility or deportability of an alien."],[0,"(2) Charges"],[1,"An alien placed in proceedings under this section may be charged with any applicable ground of inadmissibility under section 1182(a) of this title or any applicable ground of deportability under section 1227(a) of this title."],[0,"(3) Exclusive procedures"],[1,"Unless otherwise specified in this chapter, a proceeding under this section shall be the sole and exclusive procedure for determining whether an alien may be admitted to the United States or, if the alien has been so admitted, removed from the United States. Nothing in this section shall affect proceedings conducted pursuant to section 1228 of this title."],[0,"(b) Conduct of proceeding"],[0,"(1) Authority of immigration judge"],[1,"The immigration judge shall administer oaths, receive evidence, and interrogate, examine, and cross-examine the alien and any witnesses. The immigration judge may issue subpoenas for the attendance of witnesses and presentation of evidence. The immigration judge shall have authority (under regulations prescribed by the Attorney General) to sanction by civil money penalty any action (or inaction) in contempt of the judge's proper exercise of authority under this chapter."],[0,"(2) Form of proceeding"],[0,"(A) In general"],[2,"The proceeding may take place—"],[3,"(i) in person,"],[3,"(ii) where agreed to by the parties, in the absence of the alien,"],[3,"(iii) through video conference, or"],[3,"(iv) subject to subparagraph (B), through telephone conference."],[0,"(B) Consent required in certain cases"],[2,"An evidentiary hearing on the merits may only be conducted through a telephone conference with the consent of the alien involved after the alien has been advised of the right to proceed in person or through video conference."],[0,"(3) Presence of alien"],[1,"If it is impracticable by reason of an alien's mental incompetency for the alien to be present at the proceeding, the Attorney General shall prescribe safeguards to protect the rights and privileges of the alien."],[0,"(4) Alien's rights in proceeding"],[1,"In proceedings under this section, under regulations of the Attorney General—"],[2,"(A) the alien shall have the privilege of being represented, at no expense to the Government, by counsel of the alien's choosing who is authorized to practice in such proceedings,"],[2,"(B) the alien shall have a reasonable opportunity to examine the evidence against the alien, to present evidence on the alien's own behalf, and to cross-examine witnesses presented by the Government but these rights shall not entitle the alien to examine such national security information as the Government may proffer in opposition to the alien's admission to the United States or to an application by the alien for discretionary relief under this chapter, and"],[2,"(C) a complete record shall be kept of all testimony and evidence produced at the proceeding."],[0,"(5) Consequences of failure to appear"],[0,"(A) In general"],[2,"Any alien who, after written notice required under paragraph (1) or (2) of section 1229(a) of this title has been provided to the alien or the alien's counsel of record, does not attend a proceeding under this section, shall be ordered removed in absentia if the Service establishes by clear, unequivocal, and convincing evidence that the written notice was so provided and that the alien is removable (as defined in subsection (e)(2)). The written notice by the Attorney General shall be considered sufficient for purposes of this subparagraph if provided at the most recent address provided under section 1229(a)(1)(F) of this title."],[0,"(B) No notice if failure to provide address information"],[2,"No written notice shall be required under subparagraph (A) if the alien has failed to provide the address required under section 1229(a)(1)(F) of this title."],[0,"(C) Rescission of order"],[2,"Such an order may be rescinded only—"],[3,"(i) upon a motion to reopen filed within 180 days after the date of the order of removal if the alien demonstrates that the failure to appear was because of exceptional circumstances (as defined in subsection (e)(1)), or"],[3,"(ii) upon a motion to reopen filed at any time if the alien demonstrates that the alien did not receive notice in accordance with paragraph (1) or (2) of section 1229(a) of this title or the alien demonstrates that the alien was in Federal or State custody and the failure to appear was through no fault of the alien."],[2,"The filing of the motion to reopen described in clause (i) or (ii) shall stay the removal of the alien pending disposition of the motion by the immigration judge."],[0,"(D) Effect on judicial review"],[2,"Any petition for review under section 1252 of this title of an order entered in absentia under this paragraph shall (except in cases described in section 1252(b)(5) of this title) be confined to (i) the validity of the notice provided to the alien, (ii) the reasons for the alien's not attending the proceeding, and (iii) whether or not the alien is removable."],[0,"(E) Additional application to certain aliens in contiguous territory"],[2,"The preceding provisions of this paragraph shall apply to all aliens placed in proceedings under this section, including any alien who remains in a contiguous foreign territory pursuant to section 1225(b)(2)(C) of this title."],[0,"(6) Treatment of frivolous behavior"],[1,"The Attorney General shall, by regulation—"],[2,"(A) define in a proceeding before an immigration judge or before an appellate administrative body under this subchapter, frivolous behavior for which attorneys may be sanctioned,"],[2,"(B) specify the circumstances under which an administrative appeal of a decision or ruling will be considered frivolous and will be summarily dismissed, and"],[2,"(C) impose appropriate sanctions (which may include suspension and disbarment) in the case of frivolous behavior."],[1,"Nothing in this paragraph shall be construed as limiting the authority of the Attorney General to take actions with respect to inappropriate behavior."],[0,"(7) Limitation on discretionary relief for failure to appear"],[1,"Any alien against whom a final order of removal is entered in absentia under this subsection and who, at the time of the notice described in paragraph (1) or (2) of section 1229(a) of this title, was provided oral notice, either in the alien's native language or in another language the alien understands, of the time and place of the proceedings and of the consequences under this paragraph of failing, other than because of exceptional circumstances (as defined in subsection (e)(1)) to attend a proceeding under this section, shall not be eligible for relief under section 1229b, 1229c, 1255, 1258, or 1259 of this title for a period of 10 years after the date of the entry of the final order of removal."],[0,"(c) Decision and burden of proof"],[0,"(1) Decision"],[0,"(A) In general"],[2,"At the conclusion of the proceeding the immigration judge shall decide whether an alien is removable from the United States. The determination of the immigration judge shall be based only on the evidence produced at the hearing."],[0,"(B) Certain medical decisions"],[2,"If a medical officer or civil surgeon or board of medical officers has certified under section 1222(b) of this title that an alien has a disease, illness, or addiction which would make the alien inadmissible under paragraph (1) of section 1182(a) of this title, the decision of the immigration judge shall be based solely upon such certification."],[0,"(2) Burden on alien"],[1,"In the proceeding the alien has the burden of establishing—"],[2,"(A) if the alien is an applicant for admission, that the alien is clearly and beyond doubt entitled to be admitted and is not inadmissible under section 1182 of this title; or"],[2,"(B) by clear and convincing evidence, that the alien is lawfully present in the United States pursuant to a prior admission."],[1,"In meeting the burden of proof under subparagraph (B), the alien shall have access to the alien's visa or other entry document, if any, and any other records and documents, not considered by the Attorney General to be confidential, pertaining to the alien's admission or presence in the United States."],[0,"(3) Burden on service in cases of deportable aliens"],[0,"(A) In general"],[2,"In the proceeding the Service has the burden of establishing by clear and convincing evidence that, in the case of an alien who has been admitted to the United States, the alien is deportable. No decision on deportability shall be valid unless it is based upon reasonable, substantial, and probative evidence."],[0,"(B) Proof of convictions"],[2,"In any proceeding under this chapter, any of the following documents or records (or a certified copy of such an official document or record) shall constitute proof of a criminal conviction:"],[3,"(i) An official record of judgment and conviction."],[3,"(ii) An official record of plea, verdict, and sentence."],[3,"(iii) A docket entry from court records that indicates the existence of the conviction."],[3,"(iv) Official minutes of a court proceeding or a transcript of a court hearing in which the court takes notice of the existence of the conviction."],[3,"(v) An abstract of a record of conviction prepared by the court in which the conviction was entered, or by a State official associated with the State's repository of criminal justice records, that indicates the charge or section of law violated, the disposition of the case, the existence and date of conviction, and the sentence."]],"more":true,"ed":"2024","src":"https://www.govinfo.gov/link/uscode/8/1229a?type=usc&year=mostrecent&link-type=html"},"by":{"0":"3","1":"24"},"q":[{"src":"brief","b":1,"text":"decide whether an alien is removable.","cite":"8 U.S.C. 1229a(c)(1)(A)"}]},{"t":"usc","label":"28 U.S.C. § 1254","url":"https://www.law.cornell.edu/uscode/text/28/1254","subs":["(1)"],"by":{"0":"1"}},{"t":"reg","label":"64 Fed. Reg. 8,478","url":"https://www.govinfo.gov/link/fr/64/8478","by":{"0":"6, 32, 42","1":"5, 6, 28"}},{"t":"reg","label":"82 Fed. Reg. 45,161","url":"https://www.govinfo.gov/link/fr/82/45161","by":{"0":"43"}},{"t":"reg","label":"84 Fed. Reg. 3,665","url":"https://www.govinfo.gov/link/fr/84/3665","by":{"0":"44"}},{"t":"reg","label":"84 Fed. Reg. 33,829","url":"https://www.govinfo.gov/link/fr/84/33829","by":{"0":"27, 43, 44"}},{"t":"law","label":"Rules, Regulations—continued, Pub. L. No. 104-132","url":"https://www.govinfo.gov/link/plaw/104/public/132","by":{"0":"passim","2":"2, 7"}},{"t":"law","label":"Pub. L. No. 104-208","url":"https://www.govinfo.gov/link/plaw/104/public/208","by":{"0":"3, 11","1":"4","2":"7"}},{"t":"law","label":"Pub. L. No. 105-277","url":"https://www.govinfo.gov/link/plaw/105/public/277","by":{"0":"passim","1":"5, 27"}},{"t":"law","label":"Pub. L. No. 109-13","url":"https://www.govinfo.gov/link/plaw/109/public/13","by":{"0":"11, 20, 29, 30","1":"6","2":"3, 4 ,16"}},{"t":"case","label":"Abramski v. United States","cite":"573 U.S. 169","y":2014,"id":"2013/12-1493","sc":1,"by":{"1":"16"},"q":[{"src":"brief","b":1,"text":"to the statutory context, ‘structure, history, and purpose.’","cite":"573 U.S. 169, 179"}]},{"t":"case","label":"Agonafer v. Sessions","cite":"859 F.3d 1198","y":2017,"court":"9th Cir.","url":"https://www.courtlistener.com/c/F.3d/859/1198/","by":{"1":"40"}},{"t":"case","label":"Ahmed v. Mukasey","cite":"300 Fed. Appx. 324","y":2008,"court":"5th Cir.","url":"https://www.courtlistener.com/c/Fed.%20Appx./300/324/","by":{"1":"35"}},{"t":"case","label":"Al-Salehi v. INS","cite":"47 F.3d 390","y":1995,"court":"10th Cir.","url":"https://www.courtlistener.com/c/F.3d/47/390/","by":{"1":"21"}},{"t":"case","label":"Ali v. Mukasey","cite":"529 F.3d 478","y":2008,"court":"2d Cir.","url":"https://www.courtlistener.com/c/F.3d/529/478/","by":{"1":"36"}},{"t":"case","label":"Alphonsus v. Holder","cite":"705 F.3d 1031","y":2013,"court":"9th Cir.","url":"https://www.courtlistener.com/c/F.3d/705/1031/","by":{"1":"39"}},{"t":"case","label":"Bank of Am. Corp. v. City of Miami","cite":"137 S. Ct. 1296","y":2017,"id":"2016/15-1111","sc":1,"by":{"1":"22"}},{"t":"case","label":"Brotherhood of R.R. Trainmen, Enter. Lodge","cite":"321 U.S. 50","y":1944,"id":"scdb/1943-097","sc":1,"by":{"1":"38"},"q":[{"src":"brief","b":1,"text":"So long as Congress does not violate other constitutional provisions, its ‘control over the jurisdiction of the federal courts’ is ‘plenary.’","cite":"321 U.S. 50, 63-64"}]},{"t":"case","label":"Brownell v. Tom We Shung","cite":"352 U.S. 180","y":1956,"id":"1956/43","sc":1,"by":{"1":"2"}},{"t":"case","label":"Cadet v. Bulger","cite":"377 F.3d 1173","y":2004,"court":"11th Cir.","url":"https://www.courtlistener.com/c/F.3d/377/1173/","by":{"1":"31","2":"17"}},{"t":"case","label":"Cheng Fan Kwok v. INS","cite":"392 U.S. 206","y":1968,"id":"1967/638","sc":1,"by":{"1":"21","2":"13, 14"}},{"t":"case","label":"Cherichel v. Holder","cite":"591 F.3d 1002","y":2010,"url":"https://www.courtlistener.com/c/F.3d/591/1002/","by":{"1":"18"}},{"t":"case","label":"Chupina v. Holder","cite":"570 F.3d 99","y":2009,"court":"2d Cir.","url":"https://www.courtlistener.com/c/F.3d/570/99/","by":{"1":"25"}},{"t":"case","label":"Cochise Consultancy, Inc. v. United States ex rel. Hunt","cite":"139 S. Ct. 1507","y":2019,"id":"2018/18-315","sc":1,"by":{"1":"34"}},{"t":"case","label":"Cohen v. Beneficial Indus. Loan Corp.","cite":"337 U.S. 541","y":1949,"id":"scdb/1948-101","sc":1,"by":{"1":"18"}},{"t":"case","label":"Cole v. U.S. Attorney Gen.","cite":"712 F.3d 517","y":2013,"url":"https://www.courtlistener.com/c/F.3d/712/517/","by":{"1":"17"}},{"t":"case","label":"Connecticut Nat’l Bank v. Germain","cite":"503 U.S. 249","y":1992,"id":"1991/90-1791","sc":1,"by":{"1":"33"}},{"t":"case","label":"Davis v. Michigan Dep’t of Treasury","cite":"489 U.S. 803","y":1989,"id":"1988/87-1020","sc":1,"by":{"1":"16"}},{"t":"case","label":"Enwonwu v. Gonzáles","cite":"232 Fed. Appx. 11","y":2007,"court":"1st Cir.","url":"https://www.courtlistener.com/c/Fed.%20Appx./232/11/","by":{"1":"36"}},{"t":"case","label":"Escudero-Arciniega v. Holder","cite":"702 F.3d 781","y":2012,"court":"5th Cir.","url":"https://www.courtlistener.com/c/F.3d/702/781/","by":{"1":"17, 18"}},{"t":"case","label":"Garcia v. INS","cite":"7 F.3d 1320","y":1993,"court":"7th Cir.","url":"https://www.courtlistener.com/c/F.3d/7/1320/","by":{"1":"21"}},{"t":"case","label":"Garcia v. Lynch","cite":"798 F.3d 876","y":2015,"court":"9th Cir.","url":"https://www.courtlistener.com/c/F.3d/798/876/","by":{"1":"40"},"q":[{"src":"brief","b":1,"text":"does not apply to the denial of a procedural motion that rests on a ground independent of the conviction that triggers the bar.","cite":"798 F.3d 876, 881"}]},{"t":"case","label":"Gourdet v. Holder","cite":"587 F.3d 1","y":2009,"court":"1st Cir.","url":"https://www.courtlistener.com/c/F.3d/587/1/","by":{"1":"18"}},{"t":"case","label":"Henderson ex rel. Henderson v. Shinseki","cite":"562 U.S. 428","y":2011,"id":"2010/09-1036","sc":1,"by":{"1":"12"},"q":[{"src":"brief","b":1,"text":"federal courts have an independent obligation to ensure that they do not exceed the scope of their jurisdiction,","cite":"562 U.S. 428, 434"}]},{"t":"case","label":"Home Depot U.S.A., Inc. v. Jackson","cite":"139 S. Ct. 1743","y":2019,"id":"2018/17-1471","sc":1,"by":{"1":"16"},"q":[{"src":"brief","b":1,"text":"the words of [the] statute must be read in their context and with a view to their place in the overall statutory scheme.","cite":"139 S. Ct. 1743, 1748"}]},{"t":"case","label":"INS v. Cardoza-Fonseca","cite":"480 U.S. 421","y":1987,"id":"1986/85-782","sc":1,"by":{"1":"21"}},{"t":"case","label":"INS v. Doherty","cite":"502 U.S. 314","y":1992,"id":"1991/90-925","sc":1,"by":{"1":"39"}},{"t":"case","label":"INS v. Elias-Zacarias","cite":"502 U.S. 478","y":1992,"id":"1991/90-1342","sc":1,"by":{"1":"38"}},{"t":"case","label":"Ilchuk v. Attorney Gen. of the U.S.","cite":"434 F.3d 618","y":2006,"court":"3d Cir.","url":"https://www.courtlistener.com/c/F.3d/434/618/","by":{"1":"18"}},{"t":"case","label":"Ishak v. Gonzales","cite":"422 F.3d 22","y":2005,"court":"1st Cir.","url":"https://www.courtlistener.com/c/F.3d/422/22/","by":{"1":"32","2":"16"},"q":[{"src":"brief","b":2,"text":"a final administrative order of removal, deportation, or exclusion.","cite":"422 F.3d 22"}]},{"t":"case","label":"Issaq v. Holder","cite":"617 F.3d 962","y":2010,"court":"7th Cir.","url":"https://www.courtlistener.com/c/F.3d/617/962/","by":{"1":"41, 42"}},{"t":"case","label":"Keungne v. U.S. Attorney Gen.","cite":"561 F.3d 1281","y":2009,"court":"11th Cir.","url":"https://www.courtlistener.com/c/F.3d/561/1281/","by":{"1":"11, 12","2":"21"},"q":[{"src":"brief","b":1,"text":"any offense covered by section 1227(a)(2)(A)(ii) * * * for which both predicate offenses are, without regard to their date of commission, otherwise covered by section 1227(a)(2)(A)(i).","cite":"561 F.3d 1281"}]},{"t":"case","label":"Kofa v. INS","cite":"60 F.3d 1084","y":1995,"court":"4th Cir.","url":"https://www.courtlistener.com/c/F.3d/60/1084/","by":{"1":"21"}},{"t":"case","label":"Kouambo v. Barr","cite":"943 F.3d 205","y":2019,"court":"4th Cir.","url":"https://www.courtlistener.com/c/F.3d/943/205/","by":{"1":"26"}},{"t":"case","label":"Lamar, Archer & Cofrin, LLP v. Appling","cite":"138 S. Ct. 1752","y":2018,"id":"2017/16-1215","sc":1,"by":{"1":"22"}},{"t":"case","label":"Law v. Siegel","cite":"571 U.S. 415","y":2014,"id":"2013/12-5196","sc":1,"by":{"1":"34"}},{"t":"case","label":"Lenjinac v. Holder","cite":"780 F.3d 852","y":2015,"court":"7th Cir.","url":"https://www.courtlistener.com/c/F.3d/780/852/","by":{"1":"41"},"q":[{"src":"brief","b":1,"text":"conclusively held that deferral of removal is not a final remedy and therefore the INA does not bar judicial review.","cite":"780 F.3d 852, 855"}]},{"t":"case","label":"Lorillard v. Pons","cite":"434 U.S. 575","y":1978,"id":"1977/76-1346","sc":1,"by":{"1":"22","2":"10"},"q":[{"src":"brief","b":1,"text":"Congress is presumed to be aware of * * * [a] judicial interpretation of a statute and to adopt that interpretation when it re-enacts a statute without change.","cite":"434 U.S. 575, 580"}]},{"t":"case","label":"Lovan v. Holder","cite":"574 F.3d 990","y":2009,"court":"8th Cir.","url":"https://www.courtlistener.com/c/F.3d/574/990/","by":{"1":"33, 35","2":"4"}},{"t":"case","label":"Luna-Garcia v. Holder","cite":"777 F.3d 1182","y":2015,"court":"10th Cir.","url":"https://www.courtlistener.com/c/F.3d/777/1182/","by":{"1":"36"}},{"t":"case","label":"Mansoori v. INS","cite":"32 F.3d 1020","y":1994,"court":"7th Cir.","url":"https://www.courtlistener.com/c/F.3d/32/1020/","by":{"1":"21"}},{"t":"case","label":"Medrano-Olivas v. Holder","cite":"590 Fed. Appx. 770","y":2014,"court":"10th Cir.","url":"https://www.courtlistener.com/c/Fed.%20Appx./590/770/","by":{"1":"18"}},{"t":"case","label":"Mosquera-Perez v. INS","cite":"3 F.3d 553","y":1993,"court":"1st Cir.","url":"https://www.courtlistener.com/c/F.3d/3/553/","by":{"1":"21"}},{"t":"case","label":"Ogbudimkpa v. Ashcroft","cite":"342 F.3d 207","y":2003,"court":"3d Cir.","url":"https://www.courtlistener.com/c/F.3d/342/207/","by":{"1":"31"}},{"t":"case","label":"Omar v. McHugh","cite":"646 F.3d 13","y":2011,"court":"D.C. Cir.","url":"https://www.courtlistener.com/c/F.3d/646/13/","by":{"1":"33"},"q":[{"src":"brief","b":1,"text":"during a court’s review of a final order of removal,","cite":"646 F.3d 13, 18"}]},{"t":"case","label":"Ortiz-Alfaro v. Holder","cite":"694 F.3d 955","y":2012,"court":"9th Cir.","url":"https://www.courtlistener.com/c/F.3d/694/955/","by":{"1":"36"}},{"t":"case","label":"Ortiz-Franco v. Holder","cite":"782 F.3d 81","y":2015,"court":"2d Cir.","url":"https://www.courtlistener.com/c/F.3d/782/81/","by":{"1":"17, 32, 35, 42","2":"4"}},{"t":"case","label":"Patchak v. Zinke","cite":"138 S. Ct. 897","y":2018,"id":"2017/16-498","sc":1,"by":{"1":"38"},"q":[{"src":"brief","b":1,"text":"Congress’ greater power to create lower federal courts includes its lesser power to ‘limit the jurisdiction of those Courts.’","cite":"138 S. Ct. 897, 906"}]},{"t":"case","label":"Pechenkov v. Holder","cite":"705 F.3d 444","y":2012,"court":"9th Cir.","url":"https://www.courtlistener.com/c/F.3d/705/444/","by":{"1":"39, 40, 41"},"q":[{"src":"brief","b":1,"text":"the only relevant question is whether an IJ has made a finding of removability because of a relevant conviction.","cite":"705 F.3d at 451"}]},{"t":"case","label":"Ponce-Osorio v. Johnson","cite":"824 F.3d 502","y":2016,"court":"5th Cir.","url":"https://www.courtlistener.com/c/F.3d/824/502/","by":{"1":"36"}},{"t":"case","label":"Ratzlaf v. United States","cite":"510 U.S. 135","y":1994,"id":"1993/92-1196","sc":1,"by":{"1":"23"}},{"t":"case","label":"Reno v. American-Arab Anti-Discrimination Comm.","cite":"525 U.S. 471","y":1999,"id":"1998/97-1252","sc":1,"by":{"1":"37"}},{"t":"case","label":"Reno v. Bossier Parish Sch. Bd.","cite":"528 U.S. 320","y":2000,"id":"1998/98-405","sc":1,"by":{"1":"34"}},{"t":"case","label":"Saint Fort v. Ashcroft","cite":"329 F.3d 191","y":2003,"court":"1st Cir.","url":"https://www.courtlistener.com/c/F.3d/329/191/","by":{"1":"31"}},{"t":"case","label":"Saintha v. Mukasey","cite":"516 F.3d 243","y":2008,"url":"https://www.courtlistener.com/c/F.3d/516/243/","by":{"1":"18"}},{"t":"case","label":"Scenic Am., Inc. v. United States Dep’t of Transp.","cite":"836 F.3d 42","y":2016,"court":"D.C. Cir.","url":"https://www.courtlistener.com/c/F.3d/836/42/","by":{"1":"12"}},{"t":"case","label":"Shabo v. Sessions","cite":"892 F.3d 237","y":2018,"court":"6th Cir.","url":"https://www.courtlistener.com/c/F.3d/892/237/","by":{"1":"36"}},{"t":"case","label":"Shaughnessy v. Pedreiro","cite":"349 U.S. 48","y":1955,"id":"scdb/1954-069","sc":1,"by":{"1":"2"}},{"t":"case","label":"Singh v. Ashcroft","cite":"351 F.3d 435","y":2003,"court":"9th Cir.","url":"https://www.courtlistener.com/c/F.3d/351/435/","by":{"1":"31"}},{"t":"case","label":"Stone v. INS","cite":"514 U.S. 386","y":1995,"id":"1994/93-1199","sc":1,"by":{"1":"39"},"q":[{"src":"brief","b":1,"text":"every delay works to the advantage of the [removable] alien who wishes merely to remain in the United States,","cite":"514 U.S. 386, 399-400"},{"src":"argument","who":"Mr. Guarnieri","text":"This Court said as much in Stone against INS, and the text of 1252 continues to reflect it anticipates that there will be appellate proceedings with respect to motions to reopen."}]},{"t":"case","label":"Ventura-Reyes v. Lynch","cite":"797 F.3d 348","y":2015,"court":"6th Cir.","url":"https://www.courtlistener.com/c/F.3d/797/348/","by":{"1":"17, 42"}},{"t":"case","label":"Wang v. Ashcroft","cite":"320 F.3d 130","y":2003,"court":"2d Cir.","url":"https://www.courtlistener.com/c/F.3d/320/130/","by":{"1":"31"}},{"t":"case","label":"Wanjiru v. Holder","cite":"705 F.3d 258","y":2013,"court":"7th Cir.","url":"https://www.courtlistener.com/c/F.3d/705/258/","by":{"1":"41","2":"21"},"q":[{"src":"brief","b":1,"text":"(which speaks only of a final order) appears to be inapplicable.","cite":"705 F.3d 258"},{"src":"argument","who":"Mr. Hughes","text":"One is the reasoning of the Seventh Circuit of Wanjiru. 1182 just is not applicable in these circumstances because it's about admissibility and it applies to criminal convictions that are prior to the alien's technical admissibility."}]},{"t":"case","label":"Yee v. City of Escondido","cite":"503 U.S. 519","y":1992,"id":"1991/90-1947","sc":1,"by":{"1":"42","2":"21"}},{"t":"usc","label":"8 U.S.C. § 1105a","url":"https://www.law.cornell.edu/uscode/text/8/1105a","subs":["(1964)","(1982)","(a)(1964)"],"by":{"1":"20, 22, 21, 2"}},{"t":"usc","label":"8 U.S.C. § 1158","url":"https://www.law.cornell.edu/uscode/text/8/1158","subs":["(b)(2)(A)(ii)"],"by":{"1":"8, 8"}},{"t":"usc","label":"8 U.S.C. § 1225","url":"https://www.law.cornell.edu/uscode/text/8/1225","subs":["(b)(1)"],"by":{"1":"30"}},{"t":"usc","label":"8 U.S.C. § 1227","url":"https://www.law.cornell.edu/uscode/text/8/1227","subs":["(a)(2)(A)(i)","(a)(2)(A)(iii)"],"by":{"1":"8, 11, 12, 8"}},{"t":"usc","label":"8 U.S.C. § 1231","url":"https://www.law.cornell.edu/uscode/text/8/1231","subs":["(a)(5)","(b)(3)","(b)(3)(B)(ii)"],"stext":{"head":"§1231. Detention and removal of aliens ordered removed","paras":[[0,"(a) Detention, release, and removal of aliens ordered removed"],[0,"(1) Removal period"],[0,"(A) In general"],[2,"Except as otherwise provided in this section, when an alien is ordered removed, the Attorney General shall remove the alien from the United States within a period of 90 days (in this section referred to as the \"removal period\")."],[0,"(B) Beginning of period"],[2,"The removal period begins on the latest of the following:"],[3,"(i) The date the order of removal becomes administratively final."],[3,"(ii) If the removal order is judicially reviewed and if a court orders a stay of the removal of the alien, the date of the court's final order."],[3,"(iii) If the alien is detained or confined (except under an immigration process), the date the alien is released from detention or confinement."],[0,"(C) Suspension of period"],[2,"The removal period shall be extended beyond a period of 90 days and the alien may remain in detention during such extended period if the alien fails or refuses to make timely application in good faith for travel or other documents necessary to the alien's departure or conspires or acts to prevent the alien's removal subject to an order of removal."],[0,"(2) Detention"],[1,"During the removal period, the Attorney General shall detain the alien. Under no circumstance during the removal period shall the Attorney General release an alien who has been found inadmissible under section 1182(a)(2) or 1182(a)(3)(B) of this title or deportable under section 1227(a)(2) or 1227(a)(4)(B) of this title."],[0,"(3) Supervision after 90-day period"],[1,"If the alien does not leave or is not removed within the removal period, the alien, pending removal, shall be subject to supervision under regulations prescribed by the Attorney General. The regulations shall include provisions requiring the alien—"],[2,"(A) to appear before an immigration officer periodically for identification;"],[2,"(B) to submit, if necessary, to a medical and psychiatric examination at the expense of the United States Government;"],[2,"(C) to give information under oath about the alien's nationality, circumstances, habits, associations, and activities, and other information the Attorney General considers appropriate; and"],[2,"(D) to obey reasonable written restrictions on the alien's conduct or activities that the Attorney General prescribes for the alien."],[0,"(4) Aliens imprisoned, arrested, or on parole, supervised release, or probation"],[0,"(A) In general"],[2,"Except as provided in section 259(a) 1 of title 42 and paragraph (2),2 the Attorney General may not remove an alien who is sentenced to imprisonment until the alien is released from imprisonment. Parole, supervised release, probation, or possibility of arrest or further imprisonment is not a reason to defer removal."],[0,"(B) Exception for removal of nonviolent offenders prior to completion of sentence of imprisonment"],[2,"The Attorney General is authorized to remove an alien in accordance with applicable procedures under this chapter before the alien has completed a sentence of imprisonment—"],[3,"(i) in the case of an alien in the custody of the Attorney General, if the Attorney General determines that (I) the alien is confined pursuant to a final conviction for a nonviolent offense (other than an offense related to smuggling or harboring of aliens or an offense described in section 1101(a)(43)(B), (C), (E), (I), or (L) of this title 3 and (II) the removal of the alien is appropriate and in the best interest of the United States; or"],[3,"(ii) in the case of an alien in the custody of a State (or a political subdivision of a State), if the chief State official exercising authority with respect to the incarceration of the alien determines that (I) the alien is confined pursuant to a final conviction for a nonviolent offense (other than an offense described in section 1101(a)(43)(C) or (E) of this title), (II) the removal is appropriate and in the best interest of the State, and (III) submits a written request to the Attorney General that such alien be so removed."],[0,"(C) Notice"],[2,"Any alien removed pursuant to this paragraph shall be notified of the penalties under the laws of the United States relating to the reentry of deported aliens, particularly the expanded penalties for aliens removed under subparagraph (B)."],[0,"(D) No private right"],[2,"No cause or claim may be asserted under this paragraph against any official of the United States or of any State to compel the release, removal, or consideration for release or removal of any alien."],[0,"(5) Reinstatement of removal orders against aliens illegally reentering"],[1,"If the Attorney General finds that an alien has reentered the United States illegally after having been removed or having departed voluntarily, under an order of removal, the prior order of removal is reinstated from its original date and is not subject to being reopened or reviewed, the alien is not eligible and may not apply for any relief under this chapter, and the alien shall be removed under the prior order at any time after the reentry."],[0,"(6) Inadmissible or criminal aliens"],[1,"An alien ordered removed who is inadmissible under section 1182 of this title, removable under section 1227(a)(1)(C), 1227(a)(2), or 1227(a)(4) of this title or who has been determined by the Attorney General to be a risk to the community or unlikely to comply with the order of removal, may be detained beyond the removal period and, if released, shall be subject to the terms of supervision in paragraph (3)."],[0,"(7) Employment authorization"],[1,"No alien ordered removed shall be eligible to receive authorization to be employed in the United States unless the Attorney General makes a specific finding that—"],[2,"(A) the alien cannot be removed due to the refusal of all countries designated by the alien or under this section to receive the alien, or"],[2,"(B) the removal of the alien is otherwise impracticable or contrary to the public interest."],[0,"(b) Countries to which aliens may be removed"],[0,"(1) Aliens arriving at the United States"],[1,"Subject to paragraph (3)—"],[0,"(A) In general"],[2,"Except as provided by subparagraphs (B) and (C), an alien who arrives at the United States and with respect to whom proceedings under section 1229a of this title were initiated at the time of such alien's arrival shall be removed to the country in which the alien boarded the vessel or aircraft on which the alien arrived in the United States."],[0,"(B) Travel from contiguous territory"],[2,"If the alien boarded the vessel or aircraft on which the alien arrived in the United States in a foreign territory contiguous to the United States, an island adjacent to the United States, or an island adjacent to a foreign territory contiguous to the United States, and the alien is not a native, citizen, subject, or national of, or does not reside in, the territory or island, removal shall be to the country in which the alien boarded the vessel that transported the alien to the territory or island."],[0,"(C) Alternative countries"],[2,"If the government of the country designated in subparagraph (A) or (B) is unwilling to accept the alien into that country's territory, removal shall be to any of the following countries, as directed by the Attorney General:"],[3,"(i) The country of which the alien is a citizen, subject, or national."],[3,"(ii) The country in which the alien was born."],[3,"(iii) The country in which the alien has a residence."],[3,"(iv) A country with a government that will accept the alien into the country's territory if removal to each country described in a previous clause of this subparagraph is impracticable, inadvisable, or impossible."],[0,"(2) Other aliens"],[1,"Subject to paragraph (3)—"],[0,"(A) Selection of country by alien"],[2,"Except as otherwise provided in this paragraph—"],[3,"(i) any alien not described in paragraph (1) who has been ordered removed may designate one country to which the alien wants to be removed, and"],[3,"(ii) the Attorney General shall remove the alien to the country the alien so designates."],[0,"(B) Limitation on designation"],[2,"An alien may designate under subparagraph (A)(i) a foreign territory contiguous to the United States, an adjacent island, or an island adjacent to a foreign territory contiguous to the United States as the place to which the alien is to be removed only if the alien is a native, citizen, subject, or national of, or has resided in, that designated territory or island."],[0,"(C) Disregarding designation"],[2,"The Attorney General may disregard a designation under subparagraph (A)(i) if—"],[3,"(i) the alien fails to designate a country promptly;"],[3,"(ii) the government of the country does not inform the Attorney General finally, within 30 days after the date the Attorney General first inquires, whether the government will accept the alien into the country;"],[3,"(iii) the government of the country is not willing to accept the alien into the country; or"],[3,"(iv) the Attorney General decides that removing the alien to the country is prejudicial to the United States."],[0,"(D) Alternative country"],[2,"If an alien is not removed to a country designated under subparagraph (A)(i), the Attorney General shall remove the alien to a country of which the alien is a subject, national, or citizen unless the government of the country—"],[3,"(i) does not inform the Attorney General or the alien finally, within 30 days after the date the Attorney General first inquires or within another period of time the Attorney General decides is reasonable, whether the government will accept the alien into the country; or"]],"more":true,"ed":"2024","src":"https://www.govinfo.gov/link/uscode/8/1231?type=usc&year=mostrecent&link-type=html"},"by":{"1":"5, 36, 25, 25"},"q":[{"src":"brief","b":1,"text":"subject to being * * * reviewed,","cite":"8 U.S.C. 1231(a)(5)"},{"src":"opinion","who":"Opinion of the Court (Justice Kavanaugh)","text":"as part of the review of a fnal order of removal pursuant to section 242 of the Immigration and Nationality Act (8 U. S. C. 1252).","cite":"8 U. S. C. § 1231"},{"src":"opinion","who":"Opinion of the Court (Justice Kavanaugh)","text":"race, religion, nationality, membership in a particular social group, or political opinion.","cite":"8 U. S. C. § 1231(b)(3)(A)"}]},{"t":"usc","label":"8 U.S.C. § 1252","url":"https://www.law.cornell.edu/uscode/text/8/1252","subs":["(a)","(a)(1)","(a)(2)(C)","(a)(2)(D)","(a)(4)","(a)(5)","(b)(1)","(b)(4)(B)","(b)(9)","(e)","(g)"],"stext":{"head":"§1252. Judicial review of orders of removal","paras":[[0,"(a) Applicable provisions"],[0,"(1) General orders of removal"],[1,"Judicial review of a final order of removal (other than an order of removal without a hearing pursuant to section 1225(b)(1) of this title) is governed only by chapter 158 of title 28, except as provided in subsection (b) and except that the court may not order the taking of additional evidence under section 2347(c) of such title."],[0,"(2) Matters not subject to judicial review"],[0,"(A) Review relating to section 1225(b)(1)"],[2,"Notwithstanding any other provision of law (statutory or nonstatutory), including section 2241 of title 28, or any other habeas corpus provision, and sections 1361 and 1651 of such title, no court shall have jurisdiction to review—"],[3,"(i) except as provided in subsection (e), any individual determination or to entertain any other cause or claim arising from or relating to the implementation or operation of an order of removal pursuant to section 1225(b)(1) of this title,"],[3,"(ii) except as provided in subsection (e), a decision by the Attorney General to invoke the provisions of such section,"],[3,"(iii) the application of such section to individual aliens, including the determination made under section 1225(b)(1)(B) of this title, or"],[3,"(iv) except as provided in subsection (e), procedures and policies adopted by the Attorney General to implement the provisions of section 1225(b)(1) of this title."],[0,"(B) Denials of discretionary relief"],[2,"Notwithstanding any other provision of law (statutory or nonstatutory), including section 2241 of title 28, or any other habeas corpus provision, and sections 1361 and 1651 of such title, and except as provided in subparagraph (D), and regardless of whether the judgment, decision, or action is made in removal proceedings, no court shall have jurisdiction to review—"],[3,"(i) any judgment regarding the granting of relief under section 1182(h), 1182(i), 1229b, 1229c, or 1255 of this title, or"],[3,"(ii) any other decision or action of the Attorney General or the Secretary of Homeland Security the authority for which is specified under this subchapter to be in the discretion of the Attorney General or the Secretary of Homeland Security, other than the granting of relief under section 1158(a) of this title."],[0,"(C) Orders against criminal aliens"],[2,"Notwithstanding any other provision of law (statutory or nonstatutory), including section 2241 of title 28, or any other habeas corpus provision, and sections 1361 and 1651 of such title, and except as provided in subparagraph (D), no court shall have jurisdiction to review any final order of removal against an alien who is removable by reason of having committed a criminal offense covered in section 1182(a)(2) or 1227(a)(2)(A)(iii), (B), (C), or (D) of this title, or any offense covered by section 1227(a)(2)(A)(ii) of this title for which both predicate offenses are, without regard to their date of commission, otherwise covered by section 1227(a)(2)(A)(i) of this title."],[0,"(D) Judicial review of certain legal claims"],[2,"Nothing in subparagraph (B) or (C), or in any other provision of this chapter (other than this section) which limits or eliminates judicial review, shall be construed as precluding review of constitutional claims or questions of law raised upon a petition for review filed with an appropriate court of appeals in accordance with this section."],[0,"(3) Treatment of certain decisions"],[1,"No alien shall have a right to appeal from a decision of an immigration judge which is based solely on a certification described in section 1229a(c)(1)(B) of this title."],[0,"(4) Claims under the United Nations Convention"],[1,"Notwithstanding any other provision of law (statutory or nonstatutory), including section 2241 of title 28, or any other habeas corpus provision, and sections 1361 and 1651 of such title, a petition for review filed with an appropriate court of appeals in accordance with this section shall be the sole and exclusive means for judicial review of any cause or claim under the United Nations Convention Against Torture and Other Forms of Cruel, Inhuman, or Degrading Treatment or Punishment, except as provided in subsection (e)."],[0,"(5) Exclusive means of review"],[1,"Notwithstanding any other provision of law (statutory or nonstatutory), including section 2241 of title 28, or any other habeas corpus provision, and sections 1361 and 1651 of such title, a petition for review filed with an appropriate court of appeals in accordance with this section shall be the sole and exclusive means for judicial review of an order of removal entered or issued under any provision of this chapter, except as provided in subsection (e). For purposes of this chapter, in every provision that limits or eliminates judicial review or jurisdiction to review, the terms \"judicial review\" and \"jurisdiction to review\" include habeas corpus review pursuant to section 2241 of title 28, or any other habeas corpus provision, sections 1361 and 1651 of such title, and review pursuant to any other provision of law (statutory or nonstatutory)."],[0,"(b) Requirements for review of orders of removal"],[0,"With respect to review of an order of removal under subsection (a)(1), the following requirements apply:"],[0,"(1) Deadline"],[1,"The petition for review must be filed not later than 30 days after the date of the final order of removal."],[0,"(2) Venue and forms"],[1,"The petition for review shall be filed with the court of appeals for the judicial circuit in which the immigration judge completed the proceedings. The record and briefs do not have to be printed. The court of appeals shall review the proceeding on a typewritten record and on typewritten briefs."],[0,"(3) Service"],[0,"(A) In general"],[2,"The respondent is the Attorney General. The petition shall be served on the Attorney General and on the officer or employee of the Service in charge of the Service district in which the final order of removal under section 1229a of this title was entered."],[0,"(B) Stay of order"],[2,"Service of the petition on the officer or employee does not stay the removal of an alien pending the court's decision on the petition, unless the court orders otherwise."],[0,"(C) Alien's brief"],[2,"The alien shall serve and file a brief in connection with a petition for judicial review not later than 40 days after the date on which the administrative record is available, and may serve and file a reply brief not later than 14 days after service of the brief of the Attorney General, and the court may not extend these deadlines except upon motion for good cause shown. If an alien fails to file a brief within the time provided in this paragraph, the court shall dismiss the appeal unless a manifest injustice would result."],[0,"(4) Scope and standard for review"],[1,"Except as provided in paragraph (5)(B)—"],[2,"(A) the court of appeals shall decide the petition only on the administrative record on which the order of removal is based,"],[2,"(B) the administrative findings of fact are conclusive unless any reasonable adjudicator would be compelled to conclude to the contrary,"],[2,"(C) a decision that an alien is not eligible for admission to the United States is conclusive unless manifestly contrary to law, and"],[2,"(D) the Attorney General's discretionary judgment whether to grant relief under section 1158(a) of this title shall be conclusive unless manifestly contrary to the law and an abuse of discretion."],[1,"No court shall reverse a determination made by a trier of fact with respect to the availability of corroborating evidence, as described in section 1158(b)(1)(B), 1229a(c)(4)(B), or 1231(b)(3)(C) of this title, unless the court finds, pursuant to subsection (b)(4)(B), that a reasonable trier of fact is compelled to conclude that such corroborating evidence is unavailable."],[0,"(5) Treatment of nationality claims"],[0,"(A) Court determination if no issue of fact"],[2,"If the petitioner claims to be a national of the United States and the court of appeals finds from the pleadings and affidavits that no genuine issue of material fact about the petitioner's nationality is presented, the court shall decide the nationality claim."],[0,"(B) Transfer if issue of fact"],[2,"If the petitioner claims to be a national of the United States and the court of appeals finds that a genuine issue of material fact about the petitioner's nationality is presented, the court shall transfer the proceeding to the district court of the United States for the judicial district in which the petitioner resides for a new hearing on the nationality claim and a decision on that claim as if an action had been brought in the district court under section 2201 of title 28."],[0,"(C) Limitation on determination"],[2,"The petitioner may have such nationality claim decided only as provided in this paragraph."],[0,"(6) Consolidation with review of motions to reopen or reconsider"],[1,"When a petitioner seeks review of an order under this section, any review sought of a motion to reopen or reconsider the order shall be consolidated with the review of the order."],[0,"(7) Challenge to validity of orders in certain criminal proceedings"],[0,"(A) In general"],[2,"If the validity of an order of removal has not been judicially decided, a defendant in a criminal proceeding charged with violating section 1253(a) of this title may challenge the validity of the order in the criminal proceeding only by filing a separate motion before trial. The district court, without a jury, shall decide the motion before trial."]],"more":true,"ed":"2024","src":"https://www.govinfo.gov/link/uscode/8/1252?type=usc&year=mostrecent&link-type=html"},"by":{"1":"25, 25, 25, 25, 25, 25, 25, 25, 25, 25, 25, 25"},"q":[{"src":"brief","b":1,"text":"no court shall have jurisdiction to review any final order of removal against an alien who is removable by reason of having committed a criminal offense covered in","cite":"8 U.S.C. 1252(a)(2)(C)"},{"src":"brief","b":1,"text":"[ j]udicial review of all questions of law and fact * * * arising from any action taken or proceeding brought to remove an alien from the United States * * * shall be available only in judicial review of a final order under this section.","cite":"8 U.S.C. 1252(b)(9)"},{"src":"opinion","who":"Opinion of the Court (Justice Kavanaugh)","text":"as part of the review of a fnal order of removal","cite":"8 U. S. C. § 1252"},{"src":"argument","who":"Mr. Hughes","text":"The first thing it can do is, consistent with other provisions, both in FARRA and (a)(4), underscore that the various limitations of Section 1252 can be said to apply."},{"src":"argument","who":"Mr. Hughes","text":"It says judicial -- the means of judicial review is a Section 1252 petition. We think that (a)(4) confers jurisdiction in just the same way that (a)(1) does."},{"src":"argument","who":"Mr. Hughes","text":"So (a)(4) and (a)(5) is decisive textual evidence in our view that Congress understood for purposes of Section 1252, that a cause or claim under CAT that's addressed in (a)(4) is simply not a final order of removal."}]},{"t":"usc","label":"8 U.S.C. § 1253","url":"https://www.law.cornell.edu/uscode/text/8/1253","subs":["(h)(1958)"],"stext":{"head":"§1253. Penalties related to removal","paras":[[0,"(a) Penalty for failure to depart"],[0,"(1) In general"],[1,"Any alien against whom a final order of removal is outstanding by reason of being a member of any of the classes described in section 1227(a) of this title, who—"],[2,"(A) willfully fails or refuses to depart from the United States within a period of 90 days from the date of the final order of removal under administrative processes, or if judicial review is had, then from the date of the final order of the court,"],[2,"(B) willfully fails or refuses to make timely application in good faith for travel or other documents necessary to the alien's departure,"],[2,"(C) connives or conspires, or takes any other action, designed to prevent or hamper or with the purpose of preventing or hampering the alien's departure pursuant to such, or"],[2,"(D) willfully fails or refuses to present himself or herself for removal at the time and place required by the Attorney General pursuant to such order,"],[1,"shall be fined under title 18, or imprisoned not more than four years (or 10 years if the alien is a member of any of the classes described in paragraph (1)(E), (2), (3), or (4) of section 1227(a) of this title), or both."],[0,"(2) Exception"],[1,"It is not a violation of paragraph (1) to take any proper steps for the purpose of securing cancellation of or exemption from such order of removal or for the purpose of securing the alien's release from incarceration or custody."],[0,"(3) Suspension"],[1,"The court may for good cause suspend the sentence of an alien under this subsection and order the alien's release under such conditions as the court may prescribe. In determining whether good cause has been shown to justify releasing the alien, the court shall take into account such factors as—"],[2,"(A) the age, health, and period of detention of the alien;"],[2,"(B) the effect of the alien's release upon the national security and public peace or safety;"],[2,"(C) the likelihood of the alien's resuming or following a course of conduct which made or would make the alien deportable;"],[2,"(D) the character of the efforts made by such alien himself and by representatives of the country or countries to which the alien's removal is directed to expedite the alien's departure from the United States;"],[2,"(E) the reason for the inability of the Government of the United States to secure passports, other travel documents, or removal facilities from the country or countries to which the alien has been ordered removed; and"],[2,"(F) the eligibility of the alien for discretionary relief under the immigration laws."],[0,"(b) Willful failure to comply with terms of release under supervision"],[0,"An alien who shall willfully fail to comply with regulations or requirements issued pursuant to section 1231(a)(3) of this title or knowingly give false information in response to an inquiry under such section shall be fined not more than $1,000 or imprisoned for not more than one year, or both."],[0,"(c) Penalties relating to vessels and aircraft"],[0,"(1) Civil penalties"],[0,"(A) Failure to carry out certain orders"],[2,"If the Attorney General is satisfied that a person has violated subsection (d) or (e) of section 1231 of this title, the person shall pay to the Commissioner the sum of $2,000 for each violation."],[0,"(B) Failure to remove alien stowaways"],[2,"If the Attorney General is satisfied that a person has failed to remove an alien stowaway as required under section 1231(d)(2) of this title, the person shall pay to the Commissioner the sum of $5,000 for each alien stowaway not removed."],[0,"(C) No compromise"],[2,"The Attorney General may not compromise the amount of such penalty under this paragraph."],[0,"(2) Clearing vessels and aircraft"],[0,"(A) Clearance before decision on liability"],[2,"A vessel or aircraft may be granted clearance before a decision on liability is made under paragraph (1) only if a bond approved by the Attorney General or an amount sufficient to pay the civil penalty is deposited with the Commissioner."],[0,"(B) Prohibition on clearance while penalty unpaid"],[2,"A vessel or aircraft may not be granted clearance if a civil penalty imposed under paragraph (1) is not paid."],[0,"(d) Discontinuing granting visas to nationals of country denying or delaying accepting alien"],[0,"On being notified by the Attorney General that the government of a foreign country denies or unreasonably delays accepting an alien who is a citizen, subject, national, or resident of that country after the Attorney General asks whether the government will accept the alien under this section, the Secretary of State shall order consular officers in that foreign country to discontinue granting immigrant visas or nonimmigrant visas, or both, to citizens, subjects, nationals, and residents of that country until the Attorney General notifies the Secretary that the country has accepted the alien."]],"more":false,"ed":"2024","src":"https://www.govinfo.gov/link/uscode/8/1253?type=usc&year=mostrecent&link-type=html"},"by":{"1":"25"},"q":[{"src":"brief","b":1,"text":"orders denying the withholding of deportation","cite":"8 U.S.C. 1253(h)"}]},{"t":"usc","label":"8 U.S.C. § 1254","url":"https://www.law.cornell.edu/uscode/text/8/1254","subs":["(a)(4)(1958)"],"by":{"1":"19"}},{"t":"usc","label":"18 U.S.C. § 21","url":"https://www.law.cornell.edu/uscode/text/18/21","by":{"1":"7"}},{"t":"usc","label":"18 U.S.C. § 2315","url":"https://www.law.cornell.edu/uscode/text/18/2315","by":{"1":"7"}},{"t":"usc","label":"28 U.S.C. § 1291","url":"https://www.law.cornell.edu/uscode/text/28/1291","stext":{"head":"§1291. Final decisions of district courts","paras":[[0,"The courts of appeals (other than the United States Court of Appeals for the Federal Circuit) shall have jurisdiction of appeals from all final decisions of the district courts of the United States, the United States District Court for the District of the Canal Zone, the District Court of Guam, and the District Court of the Virgin Islands, except where a direct review may be had in the Supreme Court. The jurisdiction of the United States Court of Appeals for the Federal Circuit shall be limited to the jurisdiction described in sections 1292(c) and (d) and 1295 of this title."]],"more":false,"ed":"2024","src":"https://www.govinfo.gov/link/uscode/28/1291?type=usc&year=mostrecent&link-type=html"},"by":{"1":"18"},"q":[{"src":"brief","b":1,"text":"final decision[] of the district court[],","cite":"28 U.S.C. 1291"}]},{"t":"case","label":"Benslimane v. Gonzales","cite":"430 F.3d 828","y":2005,"court":"7th Cir.","url":"https://www.courtlistener.com/c/F.3d/430/828/","by":{"2":"19"},"q":[{"src":"brief","b":2,"text":"cases at the administrative level has fallen below the minimum standards of legal justice.","cite":"430 F.3d 828, 830"}]},{"t":"case","label":"Chen v. U.S. Dep’t of Justice","cite":"144 F. App’x 147","y":2005,"court":"2d Cir.","url":"https://www.courtlistener.com/c/F.%20App%E2%80%99x/144/147/","by":{"2":"17"}},{"t":"case","label":"Department of Transp. v. Association of Am. Railroads","cite":"575 U.S. 43","y":2015,"id":"2014/13-1080","sc":1,"by":{"2":"18"},"q":[{"src":"brief","b":2,"text":"The ‘check’ the judiciary provides to maintain our separation of powers is enforcement of the rule of law through judicial review.","cite":"575 U.S. 43, 76"}]},{"t":"case","label":"E.O.H.C. v. Secretary U.S. Dep’t Homeland Sec.","cite":"2020 WL 728629","y":2020,"court":"3d Cir. Feb. 13","by":{"2":"13, 18"}},{"t":"case","label":"Henderson v. United States","cite":"568 U.S. 266","y":2013,"id":"2012/11-9307","sc":1,"by":{"2":"22"},"q":[{"src":"brief","b":2,"text":"the general rule * * * that an appellate court must apply the law in effect at the time it renders its decision.","cite":"568 U.S. 266, 271"}]},{"t":"case","label":"Hosseini v. Johnson","cite":"826 F.3d 354","y":2016,"court":"6th Cir.","url":"https://www.courtlistener.com/c/F.3d/826/354/","by":{"2":"13"}},{"t":"case","label":"Kamar v. Sessions","cite":"875 F.3d 811","y":2017,"court":"6th Cir.","url":"https://www.courtlistener.com/c/F.3d/875/811/","by":{"2":"20"}},{"t":"case","label":"Lee v. Gonzales","cite":"410 F.3d 778","y":2005,"court":"5th Cir.","url":"https://www.courtlistener.com/c/F.3d/410/778/","by":{"2":"21"}},{"t":"case","label":"Lin Zheng v. Sessions","cite":"728 F. App’x 56","y":2018,"court":"2d Cir.","url":"https://www.courtlistener.com/c/F.%20App%E2%80%99x/728/56/","by":{"2":"20"}},{"t":"case","label":"Maldonado v. Lynch","cite":"786 F.3d 1155","y":2015,"court":"9th Cir.","url":"https://www.courtlistener.com/c/F.3d/786/1155/","by":{"2":"17"}},{"t":"case","label":"Mata v. Lynch","cite":"135 S. Ct. 2150","y":2015,"url":"https://www.courtlistener.com/c/S.%20Ct./135/2150/","sc":1,"by":{"2":"21"}},{"t":"case","label":"Perez v. USCIS","cite":"774 F.3d 960","y":2014,"court":"11th Cir.","url":"https://www.courtlistener.com/c/F.3d/774/960/","by":{"2":"13"}},{"t":"case","label":"Ramsameachire v. Ashcroft","cite":"357 F.3d 169","y":2004,"court":"2d Cir.","url":"https://www.courtlistener.com/c/F.3d/357/169/","by":{"2":"9"}},{"t":"case","label":"Singh v. Ashcroft","cite":"398 F.3d 396","y":2005,"court":"6th Cir.","url":"https://www.courtlistener.com/c/F.3d/398/396/","by":{"2":"9"}},{"t":"case","label":"Sivakaran v. Ashcroft","cite":"368 F.3d 1028","y":2004,"court":"8th Cir.","url":"https://www.courtlistener.com/c/F.3d/368/1028/","by":{"2":"9"}},{"t":"case","label":"Subrata v. Attorney Gen. of U.S.","cite":"378 F. App’x 226","y":2010,"court":"3d Cir.","url":"https://www.courtlistener.com/c/F.%20App%E2%80%99x/378/226/","by":{"2":"17"}},{"t":"case","label":"Sure-Tan, Inc. v. NLRB","cite":"467 U.S. 883","y":1984,"id":"1983/82-945","sc":1,"by":{"2":"22"}},{"t":"case","label":"Tilley v. Gonzales","cite":"228 F. App’x 585","y":2007,"court":"6th Cir.","url":"https://www.courtlistener.com/c/F.%20App%E2%80%99x/228/585/","by":{"2":"8"}},{"t":"case","label":"Trinidad y Garcia v. Thomas","cite":"683 F.3d 952","y":2012,"court":"9th Cir.","url":"https://www.courtlistener.com/c/F.3d/683/952/","by":{"2":"4"}},{"t":"case","label":"Vinh Tan Nguyen v. Holder","cite":"763 F.3d 1022","y":2014,"court":"9th Cir.","url":"https://www.courtlistener.com/c/F.3d/763/1022/","by":{"2":"9"}},{"t":"case","label":"Yeremin v. Holder","cite":"738 F.3d 708","y":2013,"court":"6th Cir.","url":"https://www.courtlistener.com/c/F.3d/738/708/","by":{"2":"21"}},{"t":"case","label":"Zelaya v. Holder","cite":"668 F.3d 159","y":2012,"court":"4th Cir.","url":"https://www.courtlistener.com/c/F.3d/668/159/","by":{"2":"9"}},{"t":"reg","label":"8 C.F.R. § 1208.17","url":"https://www.ecfr.gov/current/title-8/section-1208.17","subs":["(b)(1)"],"by":{"2":"5"}},{"t":"usc","label":"28 U.S.C. § 2342","url":"https://www.law.cornell.edu/uscode/text/28/2342","by":{"2":"16"}}]};